<?php
namespace App\Services;
use App\Models\{AttendanceRecord,Employee};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class AttendanceService {
 public function status(Employee $e): array { $e->loadMissing('workSchedule'); $rows=$e->attendanceRecords()->whereDate('registered_at',today())->orderBy('registered_at')->get(); $last=$rows->last(); $flow=$this->flow($e); $completed=$rows->pluck('event_type'); $next=null; foreach($flow as $candidate){if(!$completed->contains($candidate)){$next=$candidate;break;}} return ['current_status'=>$last?->event_type ?? 'not_started','next_event'=>$next,'flow'=>$flow,'last_entry'=>$last,'records'=>$rows]; }
 public function record(Employee $e,string $event,array $data): AttendanceRecord { return DB::transaction(function()use($e,$event,$data){$e=Employee::with('workSchedule.days')->lockForUpdate()->findOrFail($e->id); if(!$e->workSchedule) throw ValidationException::withMessages(['schedule'=>'El empleado no tiene un horario laboral asignado.']); $s=$this->status($e); if($s['next_event']!==$event) throw ValidationException::withMessages(['event_type'=>'La marca esperada es '.($s['next_event']??'ninguna').'.']); $schedule=$e->workSchedule->days->firstWhere('day_of_week',now()->dayOfWeek); $late=0;$punct=null; if($event==='clock_in' && $schedule){$limit=today()->setTimeFromTimeString($schedule->start_time)->addMinutes($schedule->tolerance_minutes);$late=max(0,$limit->diffInMinutes(now(),false));$punct=$late>0?'late':'on_time';}
 $break=[]; $limits=['breakfast_end'=>['breakfast_start',(int)($schedule?->breakfast_minutes??30)],'lunch_end'=>['lunch_start',(int)($schedule?->lunch_minutes??60)]];
 if(isset($limits[$event])){[$startType,$limit]=$limits[$event];$start=$s['records']->firstWhere('event_type',$startType);$duration=$start?(int)ceil($start->registered_at->diffInSeconds(now())/60):0;$excess=max(0,$duration-$limit);$break=['break_duration_minutes'=>$duration,'break_limit_minutes'=>$limit,'break_excess_minutes'=>$excess,'break_compliance'=>$excess>0?'exceeded':'within_limit'];}
 $overtime=[]; if($event==='clock_out'){if($schedule?->end_time){$end=today()->setTimeFromTimeString($schedule->end_time);$start=today()->setTimeFromTimeString($schedule->start_time);if($end->lessThanOrEqualTo($start))$end->addDay();$minutes=max(0,$end->diffInMinutes(now(),false));$overtime=['overtime_minutes'=>$minutes,'overtime_reason'=>$minutes?'after_schedule':null];}else{$clockIn=$s['records']->firstWhere('event_type','clock_in');$breakMinutes=(int)$s['records']->sum('break_duration_minutes');$minutes=$clockIn?max(0,(int)$clockIn->registered_at->diffInMinutes(now())-$breakMinutes):0;$overtime=['overtime_minutes'=>$minutes,'overtime_reason'=>$minutes?'non_working_day':null];}}
 return AttendanceRecord::create($data+$break+$overtime+['employee_id'=>$e->id,'event_type'=>$event,'type'=>$event==='clock_out'?'out':'in','registered_at'=>now(),'work_mode'=>$e->work_mode,'punctuality'=>$punct,'late_minutes'=>$late]); }); }
 private function flow(Employee $e): array { $flow=['clock_in']; if($e->workSchedule?->has_breakfast)$flow=array_merge($flow,['breakfast_start','breakfast_end']); if($e->workSchedule?->has_lunch)$flow=array_merge($flow,['lunch_start','lunch_end']); $flow[]='clock_out'; return $flow; }
}
